import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Heuristic function (Manhattan distance)
    def heuristic(u):
        return abs(u - t)

    # Priority queue: (estimated total cost, current node, current cost)
    priority_queue = [(heuristic(s), s, 0)]
    visited = [False] * n
    min_cost = {i: float('inf') for i in range(n)}
    min_cost[s] = 0

    while priority_queue:
        _, current, cost = heapq.heappop(priority_queue)
        if visited[current]:
            continue
        visited[current] = True

        if current == t:
            return cost

        for neighbor, weight in adj[current]:
            new_cost = cost + weight
            if new_cost < min_cost[neighbor]:
                min_cost[neighbor] = new_cost
                heapq.heappush(priority_queue, (new_cost + heuristic(neighbor), neighbor, new_cost))

    return -1
```

