def solve(nums, k):
    def counting_sort(arr, exp):
        count = [0] * 20001
        for num in arr:
            count[num + 10000 + exp] += 1
        for i in range(1, 20001):
            count[i] += count[i - 1]
        output = [0] * len(arr)
        for i in reversed(range(len(arr))):
            num = arr[i]
            output[count[num + 10000 + exp] - 1] = num
            count[num + 10000 + exp] -= 1
        return output

    def kth_smallest(arr, k):
        min_val = min(arr)
        max_val = max(arr)
        exp = 0
        while min_val + exp <= max_val:
            arr = counting_sort(arr, exp)
            exp += 1
        return arr[k - 1]

    return kth_smallest(nums, k)
