        adj[u].append((v, w))

    # Track visited nodes and distances
    visited = [False] * n
    min_distance = [float('inf')] * n
    min_distance[s] = 0

    # DFS with memoization
    def dfs(node):
        if node == t:
            return 0
        if visited[node]:
            return float('inf')
        visited[node] = True
        min_dist = float('inf')
        for neighbor, weight in adj[node]:
            if not visited[neighbor]:
                res = dfs(neighbor)
                if res != float('inf'):
                    min_dist = min(min_dist, weight + res)
        visited[node] = False
        return min_dist

    result = dfs(s)
    return result if result != float('inf') else -1
