import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Heuristic function (Manhattan distance)
    def heuristic(u):
        return abs(u - t)

    # A* algorithm
    priority_queue = []
    heapq.heappush(priority_queue, (heuristic(s), 0, s))
    visited = [False] * n
    distances = [float('inf')] * n
    distances[s] = 0

    while priority_queue:
        _, cost, u = heapq.heappop(priority_queue)
        if visited[u]:
            continue
        visited[u] = True

        if u == t:
            return cost

        for v, weight in graph[u]:
            if distances[v] > cost + weight:
                distances[v] = cost + weight
                heapq.heappush(priority_queue, (distances[v] + heuristic(v), distances[v], v))

    return -1
