def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Binary search on the possible path weight
    low = 0
    high = 100 * 600  # Max possible weight (600 edges * 100)

    def is_possible(weight):
        dist = [-1] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.hefulp(heap)
            if d > weight:
                continue
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] == -1 or dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist[t] != -1

    # Binary search to find the minimum weight
    answer = -1
    while low <= high:
        mid = (low + high) // 2
        if is_possible(mid):
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    return answer if answer != -1 else -1
