from collections import deque

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Bidirectional BFS
    start_queue = deque()
    goal_queue = deque()
    start_queue.append((start_row, start_col))
    goal_queue.append((goal_row, goal_col))

    start_visited = set()
    start_visited.add((start_row, start_col))
    goal_visited = set()
    goal_visited.add((goal_row, goal_col))

    start_path = { (start_row, start_col): [start] }
    goal_path = { (goal_row, goal_col): [goal] }

    while start_queue and goal_queue:
        # Expand start side
        for _ in range(len(start_queue)):
            curr_row, curr_col = start_queue.popleft()
            for dr, dc in directions:
                nr, nc = curr_row + dr, curr_col + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in start_visited:
                    start_visited.add((nr, nc))
                    start_queue.append((nr, nc))
                    start_path[(nr, nc)] = start_path[(curr_row, curr_col)] + [(nr, nc)]
                    if (nr, nc) in goal_visited:
                        path = start_path[(nr, nc)] + goal_path[(nr, nc)][::-1][1:]
                        return path

        # Expand goal side
        for _ in range(len(goal_queue)):
            curr_row, curr_col = goal_queue.popleft()
            for dr, dc in directions:
                nr, nc = curr_row + dr, curr_col + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in goal_visited:
                    goal_visited.add((nr, nc))
                    goal_queue.append((nr, nc))
                    goal_path[(nr, nc)] = goal_path[(curr_row, curr_col)] + [(nr, nc)]
                    if (nr, nc) in start_visited:
                        path = start_path[(nr, nc)] + goal_path[(nr, nc)][::-1][1:]
                        return path

    return []
