        return []
    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def dfs(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                result = dfs(nr, nc, path + [(r, c)])
