def solve(grid, start, goal):
    if not grid or not grid[0] or start == goal:
        if (start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]) or
            grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#'):
            return []
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def idastar(start, goal, grid, rows, cols, directions):
        def dfs(node, g, path, threshold):
            f = g + manhattan(node, goal)
            if f > threshold:
                return f, None
            if node == goal:
                return 0, path
            min_threshold = float('inf')
            for dx, dy in directions:
                nx, ny = node[0] + dx, node[1] + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                    next_node = (nx, ny)
                    if next_node not in path:
                        new_path = path + [next_node]
                        res, _ = dfs(next_node, g + 1, new_path, threshold)
                        if res == float('inf'):
                            continue
                        min_threshold = min(min_threshold, res)
            return min_threshold, path

        threshold = manhattan(start, goal)
        while True:
            result, path = dfs(start, 0, [start], threshold)
            if result == float('inf'):
                return []
            if result == 0:
                return path
            threshold = result

    return idastar(start, goal, grid, rows, cols, directions)
