def solve(nums, k):
    def count_less_equal(val, nums):
        cnt = 0
        for num in nums:
            if num <= val:
                cnt += 1
            if cnt >= k:
                return True
        return cnt >= k

    left, right = min(nums), max(nums)
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid, nums):
            right = mid
        else:
            left = mid + 1
