    visited = set()
    heap = [(0, start[0], start[1])]

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = prev[(r, c)]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
