import heapq

def solve(nums, k):
    def custom_heapify(heap, n, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and heap[left] > heap[largest]:
            largest = left
        if right < n and heap[right] > heap[largest]:
            largest = right

        if largest != i:
            heap[i], heap[largest] = heap[largest], heap[i]
            custom_heapify(heap, n, largest)

    def build_max_heap(heap):
        n = len(heap)
        for i in range(n // 2 - 1, -1, -1):
            custom_heapify(heap, n, i)

    def extract_max(heap):
        if not heap:
            return None
        max_val = heap[0]
        heap[0] = heap[-1]
        heap.pop()
        custom_heapify(heap, len(heap), 0)
        return max_val

    def kth_smallest(nums, k):
        n = len(nums)
        heap = [0] * n
        for i in range(n):
            heap[i] = nums[i]
        build_max_heap(heap)
        for _ in range(k - 1):
            extract_max(heap)
        return heap[0]

    return kth_smallest(nums, k)
