def solve(n, edges):
    def dfs(node, visited):
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                dfs(neighbor, visited)

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    components = 0

    for node in range(n):
        if node not in visited:
            dfs(node, visited)
            components += 1

    return components
