    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_valid(r + dr, c + dc)]

    def backtrack(path, current):
        if current == goal:
            return path + [current]
        for neighbor in get_neighbors(*current):
            if neighbor not in path:
                result = backtrack(path + [current], neighbor)
                if result:
                    return result
        return None

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]
