    path = {}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited

    from collections import deque
    queue = deque()
    queue.append(start)
    visited.add(start)

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                visited.add((nr, nc))
                path[(nr, nc)] = (r, c)
                queue.append((nr, nc))
                if (nr, nc) == goal:
                    queue.clear()
