def solve(grid, start, goal):
    if not grid or start == goal:
        if is_free(grid, start):
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(cell):
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def backtrack(path, visited):
        r, c = path[-1]
        if (r, c) == goal:
            return path
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free((nr, nc)) and (nr, nc) not in visited:
                visited.add((nr, nc))
                result = backtrack(path + [(nr, nc)], visited)
                if result:
                    return result
                visited.remove((nr, nc))
        return None

    if not is_free(start) or not is_free(goal):
        return []

    visited = set()
    visited.add(start)
    return backtrack([start], visited)
