def solve(haystack, needle):
    if len(needle) == 0:
        return 0
    if len(needle) > len(haystack):
        return -1

    def bad_char_table(pattern):
        table = {}
        for i, char in enumerate(pattern):
            table[char] = i
        return table

    def boyer_moore_search(text, pattern, bad_char):
        len_text = len(text)
        len_pattern = len(pattern)
        bad_char_table = bad_char(pattern)
        i = 0
        while i <= len_text - len_pattern:
            j = len_pattern - 1
            while j >= 0 and text[i + j] == pattern[j]:
                j -= 1
            if j < 0:
                return i
            i += max(1, j - bad_char_table.get(text[i + j], -1))
        return -1

    return boyer_moore_search(haystack, needle, bad_char_table)
