def solve(haystack, needle):
    if len(needle) == 0:
        return 0
    if len(needle) > len(haystack):
        return -1

    # Concatenate needle + '#' + haystack and compute Z-array
    s = needle + '#' + haystack
    n = len(s)
    Z = [0] * n
    l, r = 0, 0

    for i in range(1, n):
        if i <= r:
            Z[i] = min(r - i + 1, Z[i - l])
        while i + Z[i] < n and s[Z[i]] == s[i + Z[i]]:
            Z[i] += 1
        if i + Z[i] - 1 > r:
            l = i
            r = i + Z[i] - 1

    # Check if any position in the haystack matches the needle
    for i in range(len(needle) + 1, len(s)):
        if Z[i] >= len(needle):
            return i - len(needle) - 1
    return -1
```

