def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    # Build the transition table for the finite automaton
    def build_transition_table(pattern):
        m = len(pattern)
        transition = [[0] * 26 for _ in range(m + 1)]
        for state in range(m + 1):
            for char in range(26):
                c = chr(ord('a') + char)
                if state < m and c == pattern[state]:
                    transition[state][char] = state + 1
                else:
                    fail = transition[state][char] if state < m else 0
                    while fail > 0 and c != pattern[fail - 1]:
                        fail = transition[fail - 1][char]
                    transition[state][char] = fail
        return transition

    # Simulate the finite automaton on the haystack
    transition = build_transition_table(needle)
    state = 0
    for i, char in enumerate(haystack):
        c = ord(char) - ord('a')
        state = transition[state][c]
        if state == len(needle):
            return i - len(needle) + 1
    return -1
```

