def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    class State:
        def __init__(self):
            self.next = {}
            self.link = -1
            self.len = 0

    sa = [State()]
    last = 0

    for c in haystack:
        p = last
        curr = len(sa)
        sa.append(State())
        sa[curr].len = sa[p].len + 1
        while p >= 0 and c not in sa[p].next:
            sa[p].next[c] = curr
            p = sa[p].link
        if p == -1:
            sa[curr].link = 0
        else:
            q = sa[p].next[c]
            if sa[p].len + 1 == sa[q].len:
                sa[curr].link = q
            else:
                clone = len(sa)
                sa.append(State())
                sa[clone].len = sa[p].len + 1
                sa[clone].next = sa[q].next.copy()
                sa[clone].link = sa[q].link
                while p >= 0 and sa[p].next[c] == q:
                    sa[p].next[c] = clone
                    p = sa[p].link
                sa[q].link = clone
                sa[curr].link = clone
        last = curr

    current = 0
    for c in needle:
        if c not in sa[current].next:
            return -1
        current = sa[current].next[c]

    return len(haystack) - sa[current].len
