def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    class State:
        def __init__(self):
            self.next = {}  # Maps characters to state indices
            self.link = -1  # suffix link
            self.len = 0    # Length of the longest substring

    def build_suffix_automaton(s):
        size = len(s)
        states = [State()]
        last = 0
        for i in range(size):
            curr = len(states)
            states.append(State())
            states[curr].len = states[last].len + 1
            p = last
            while p >= 0 and s[i] not in states[p].next:
                states[p].next[s[i]] = curr
                p = states[p].link
            if p == -1:
                states[curr].link = 0
            else:
                q = states[p].next[s[i]]
                if states[p].len + 1 == states[q].len:
                    states[curr].link = q
                else:
                    clone = len(states)
                    states.append(State())
                    states[clone].len = states[p].len + 1
                    states[clone].next = states[q].next.copy()
                    states[clone].link = states[q].link
                    while p >= 0 and states[p].next[s[i]] == q:
                        states[p].next[s[i]] = clone
                        p = states[p].link
                    states[q].link = clone
                    states[curr].link = clone
            last = curr
        return states

    def find_substring(sa, s, pattern):
        state = 0
        for ch in pattern:
            if ch not in sa[state].next:
                return -1
            state = sa[state].next[ch]
        return sa[state].len - len(pattern)  # Ensure it's the start index

    sa = build_suffix_automaton(haystack)
    return find_substring(sa, haystack, needle)
```

