def solve(nums):
    low, high = 1, len(nums) - 1
    while low < high:
        mid = (low + high) // 2
        count = sum(1 for num in nums if low <= num <= mid)
        if count > mid - low + 1:
            low = mid + 1
        else:
            high = mid
    return low
