def solve(nums):
    if len(nums) <= 1:
        return len(nums)

    mid = len(nums) // 2
    left = nums[:mid]
    right = nums[mid:]

    left_length = solve(left)
    right_length = solve(right)

    # Merge the results by finding the longest increasing subsequence that spans both halves
    max_len = max(left_length, right_length)
    i = j = 0
    merged = []
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])

    # Find the longest increasing subsequence in the merged list
    lis = [1] * len(merged)
    for i in range(1, len(merged)):
        for j in range(i):
            if merged[j] < merged[i]:
                lis[i] = max(lis[i], lis[j] + 1)
    return max(lis)
