import sys
import math

class SegmentTree:
    def __init__(self, size):
        self.n = 1
        while self.n < size:
            self.n <<= 1
        self.size = self.n
        self.tree = [0] * (2 * self.n)

    def update(self, pos, value):
        pos += self.n
        if self.tree[pos] >= value:
            return
        self.tree[pos] = value
        while pos > 1:
            pos >>= 1
            new_val = max(self.tree[2 * pos], self.tree[2 * pos + 1])
            if self.tree[pos] == new_val:
                break
            self.tree[pos] = new_val

    def query(self, l, r):
        res = 0
        l += self.n
        r += self.n
        while l <= r:
            if l % 2 == 1:
                res = max(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = max(res, self.tree[r])
                r -= 1
            l >>= 1
            r >>= 1
        return res

def solve(nums):
    max_val = max(nums)
    min_val = min(nums)
    range_size = max_val - min_val + 1
    st = SegmentTree(range_size)
    for num in nums:
        left = min_val
        right = num - 1
        if left <= right:
            length = st.query(left - min_val, right - min_val)
            st.update(num - min_val, length + 1)
    return st.query(0, range_size - 1)
