import bisect

def solve(nums):
    from collections import defaultdict

    class SegmentTreeNode:
        def __init__(self, l, r):
            self.l = l
            self.r = r
            self.left = None
            self.right = None
            self.max_len = 0

    def build_segment_tree(l, r):
        node = SegmentTreeNode(l, r)
        if l == r:
            return node
        mid = (l + r) // 2
        node.left = build_segment_tree(l, mid)
        node.right = build_segment_tree(mid + 1, r)
        return node

    def update(node, idx, value):
        if node.l == node.r == idx:
            node.max_len = max(node.max_len, value)
            return
        mid = (node.l + node.r) // 2
        if idx <= mid:
            update(node.left, idx, value)
        else:
            update(node.right, idx, value)
        node.max_len = max(node.left.max_len, node.right.max_len)

    def query(node, idx):
        if node.l == node.r == idx:
            return node.max_len
        mid = (node.l + node.r) // 2
        if idx <= mid:
            return query(node.left, idx)
        else:
            return query(node.right, idx)

    n = len(nums)
    root = build_segment_tree(-10000, 10000)
    for i in range(n):
        max_len = 1
        for j in range(i):
            if nums[j] < nums[i]:
                max_len = max(max_len, query(root, nums[j]) + 1)
        update(root, nums[i], max_len)
    return query(root, 10000)
