from functools import lru_cache

def solve(nums):
    @lru_cache(maxsize=None)
    def dfs(i):
        if i == len(nums):
            return 0
        max_len = 1
        for j in range(i + 1, len(nums)):
            if nums[j] > nums[i]:
                max_len = max(max_len, 1 + dfs(j))
        return max_len

    return max(dfs(i) for i in range(len(nums)))
