def solve(intervals):
    def backtrack(start_idx, removed_count, last_end):
        if start_idx == len(intervals):
            return removed_count
        # Option 1: Remove the current interval
        remove_count = backtrack(start_idx + 1, removed_count + 1, last_end)
        # Option 2: Keep the current interval if it doesn't overlap with last_end
        if intervals[start_idx][0] >= last_end:
            keep_count = backtrack(start_idx + 1, removed_count, intervals[start_idx][1])
            return min(remove_count, keep_count)
        return remove_count

    return backtrack(0, 0, -float('inf'))
