def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    # Build an interval tree
    class IntervalTreeNode:
        def __init__(self, start, end):
            self.start = start
            self.end = end
            self.left = None
            self.right = None
            self.intervals = []

    # Insert intervals into the tree
    def insert(node, start, end):
        if node is None:
            return IntervalTreeNode(start, end)
        if end < node.start:
            node.left = insert(node.left, start, end)
        elif start > node.end:
            node.right = insert(node.right, start, end)
        else:
            node.intervals.append([start, end])
        return node

    root = None
    for start, end in sorted_intervals:
        root = insert(root, start, end)

    # Count the minimum number of intervals to remove
    def count_removals(node, last_end):
        if node is None:
            return 0
        # Check left subtree for intervals that end before or at last_end
        left_count = 0
        curr = node.left
        while curr and curr.end <= last_end:
            left_count += 1
            curr = curr.right
        # Check current node's intervals
        curr_count = 0
        for interval in node.intervals:
            if interval[1] <= last_end:
                curr_count += 1
            else:
                break
        # Check right subtree for intervals that start after last_end
        right_count = 0
        curr = node.right
        while curr and curr.start > last_end:
            right_count += 1
            curr = curr.left
        # Recursively count removals in left and right subtrees
        return curr_count + left_count + right_count + count_removals(node.right, max(last_end, node.end)) + count_removals(node.left, last_end)

    # Start counting from the beginning
    return count_removals(root, -float('inf'))
