def solve(n, edges):
    def has_cycle(node, visited, recursion_stack, graph):
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if has_cycle(neighbor, visited, recursion_stack, graph):
                    return True
            elif neighbor in recursion_stack:
                return True
        recursion_stack.remove(node)
