def solve(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Floyd's Cycle-Finding algorithm
    def has_cycle(start):
        if not adj[start]:
            return False
        slow = start
        fast = start
        # First phase: find intersection point of Floyd's tortoise and hare
        while True:
            if not adj[slow]:
                return False
            slow = adj[slow][0]
            if not adj[fast]:
                return False
            fast = adj[fast][0]
            if not adj[fast]:
                return False
            fast = adj[fast][0]
            if slow == fast:
                # Second phase: find the cycle length
                cycle_len = 0
                while True:
                    slow = adj[slow][0]
                    cycle_len += 1
                    if slow == fast:
                        break
                # Third phase: check if the cycle is at least length 3
                if cycle_len >= 3:
                    return True
                else:
                    return False
        return False

    # Check each node as a potential start
    for i in range(n):
        if has_cycle(i):
            return True
    return False
