from collections import deque

def solve(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Track visited nodes
    visited = [False] * n

    def has_cycle(start):
        queue = deque()
        queue.append((start, -1))  # (current node, parent node)
        visited[start] = True

        while queue:
            node, parent = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, node))
                elif neighbor != parent:
                    return True  # Found a back edge, cycle exists
        return False

    # Check each unvisited node for cycles
    for i in range(n):
        if not visited[i]:
            if has_cycle(i):
                return True
    return False
