def solve(n, prerequisites):
    from collections import defaultdict

    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    order = []

    def backtrack(node):
        if node is None:
            return True
        if node in order:
            return False
        order.append(node)
        for neighbor in graph[node]:
            if in_degree[neighbor] == 0:
                in_degree[neighbor] = -1  # Mark as visited
                if not backtrack(neighbor):
                    return False
                in_degree[neighbor] = 0  # Restore in-degree
        return True

    for i in range(n):
        if in_degree[i] == 0:
            if not backtrack(i):
                return []
    return order if len(order) == n else []
