def solve(n, prerequisites):
    from collections import defaultdict

    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    stack = []
    visited = [False] * n

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        stack.append(node)

    for i in range(n):
        if in_degree[i] == 0 and not visited[i]:
            dfs(i)

    return stack if len(stack) == n else []
```

