def solve(n, edges):
    def has_cycle(node, visited, rec_stack, adj):
        visited[node] = True
        rec_stack[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if has_cycle(neighbor, visited, rec_stack, adj):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[node] = False
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    rec_stack = [False] * n

    for node in range(n):
        if not visited[node]:
            if has_cycle(node, visited, rec_stack, adj):
                return True

    return False
```

