def solve(n, edges):
    def has_cycle(node, visited, recursion_stack, graph):
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if has_cycle(neighbor, visited, recursion_stack, graph):
                    return True
            elif neighbor in recursion_stack:
                return True
        recursion_stack.remove(node)
        return False

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    recursion_stack = set()
    for node in range(n):
        if node not in visited:
            if has_cycle(node, visited, recursion_stack, graph):
                return True
    return False
```

