def solve(nums):
    def longest_increasing_subsequence_starting_at(i):
        if i == len(nums):
            return 0
        max_len = 1
        for j in range(i + 1, len(nums)):
            if nums[j] > nums[i]:
                current_len = 1 + longest_increasing_subsequence_starting_at(j)
                max_len = max(max_len, current_len)
        return max_len

    max_length = 1
    for i in range(len(nums)):
        current_length = longest_increasing_subsequence_starting_at(i)
        max_length = max(max_length, current_length)
    return max_length
