def solve(nums, target):
    def find_first(expect):
        left, right = 0, len(nums) - 1
        res = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == expect:
                res = mid
                right = mid - 1
            elif nums[mid] < expect:
                left = mid + 1
            else:
                right = mid - 1
        return res

    first = find_first(target)
    if first == -1:
        return [-1, -1]
    last = find_first(target)
    while last < len(nums) and nums[last] == target:
        last += 1
    return [first, last - 1]
```

