def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize distance array with infinity
    import math
    INF = math.inf
    dist = [INF] * n
    dist[s] = 0

    # Bellman-Ford algorithm
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == INF:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != INF else -1
