def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    # Build the finite automaton
    def build_automaton(pattern):
        m = len(pattern)
        automaton = [{} for _ in range(m + 1)]
        for state in range(m + 1):
            for char, next_state in automaton[state].items():
                automaton[next_state][char] = automaton[next_state].get(char, state)
        return automaton

    # Search using the automaton
    def search(text, automaton):
        m = len(text)
        state = 0
        for i in range(m):
            while state > 0 and text[i] not in automaton[state]:
                state = automaton[state].get(text[i], 0)
            if text[i] in automaton[state]:
                state = automaton[state][text[i]]
            if state == len(needle):
                return i - len(needle) + 1
        return -1

    automaton = build_automaton(needle)
    return search(haystack, automaton)
```

