def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    base = 256
    mod = 10**9 + 7

    # Precompute the hash of the needle
    needle_hash = 0
    for c in needle:
        needle_hash = (needle_hash * base + ord(c)) % mod

    # Precompute the power value for the length of the needle
    power = pow(base, len(needle) - 1, mod)

    # Compute the hash of the first window of haystack
    window_hash = 0
    for i in range(len(needle)):
        window_hash = (window_hash * base + ord(haystack[i])) % mod

    for i in range(len(haystack) - len(needle) + 1):
        if window_hash == needle_hash:
            if haystack[i:i+len(needle)] == needle:
                return i
        # Update the hash for the next window
        if i < len(haystack) - len(needle):
            window_hash = (window_hash - ord(haystack[i]) * power) % mod
            window_hash = (window_hash * base + ord(haystack[i + len(needle)])) % mod

    return -1
