def solve(nums):
    # Floyd's Tortoise and Hare algorithm to find the cycle entrance (the duplicate)
    def find_cycle():
        tortoise = nums[0]
        hare = nums[0]
        while True:
            tortoise = nums[tortoise]
            hare = nums[nums[hare]]
            if tortoise == hare:
                break
        # Find the entrance of the cycle
        tortoise = nums[0]
        while tortoise != hare:
            tortoise = nums[tortoise]
            hare = nums[hare]
        return hare
    return find_cycle()
