def solve(n):
    def fast_doubling(n):
        if n == 0:
            return (0, 1)
        a, b = fast_doubling(n >> 1)
        c = a * ((2 * b - a) if n & 1 else b)
        d = a * a + b * b
        return (d, c + d) if n & 1 else (c, d)
    return fast_doubling(n)[0]
