def solve(nums):
    piles = []
    for num in nums:
        left, right = 0, len(piles)
        while left < right:
            mid = (left + right) // 2
            if piles[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left == 0 or piles[left - 1] < num:
            piles.append(num)
        else:
            piles[left - 1] = num
    return len(piles)
