def solve(intervals):
    # Initialize a list of buckets. Each bucket will store intervals that overlap.
    # Since end values are up to 10000, we can use a list of size 10001.
    buckets = [[] for _ in range(10001)]

    # Place each interval into the appropriate bucket based on its start value
    for start, end in intervals:
        buckets[start].append(end)

    # Merge intervals by processing each bucket in order
    merged = []
    for start in range(10001):
        if not buckets[start]:
            continue
        # Find the maximum end in the current bucket and any overlapping buckets
        current_end = buckets[start][-1]
        for next_start in range(start + 1, 10001):
            if next_start <= current_end:
                current_end = max(current_end, buckets[next_start][-1])
            else:
                break
        merged.append([start, current_end])

    return merged
