from collections import defaultdict

def solve(nums, k):
    freq = defaultdict(int)
    for num in nums:
        freq[num] += 1

    # Sort items by frequency in descending order
    sorted_items = sorted(freq.items(), key=lambda x: (-x[1], x[0]))

    # Group by frequency and collect elements with the same frequency
    grouped = []
    current_freq = None
    current_group = []
    for num, count in sorted_items:
        if count != current_freq:
            if current_freq is not None:
                grouped.append((current_freq, current_group))
            current_freq = count
            current_group = [num]
        else:
            current_group.append(num)

    if current_freq is not None:
        grouped.append((current_freq, current_group))

    # Collect all elements in the top k frequency groups
    result = []
    for i in range(k):
        if i < len(grouped):
            result.extend(grouped[i][1])

    return result
