def solve(intervals):
    def backtrack(start, count):
        if start == len(intervals):
            return count
        # Option 1: Skip the current interval
        min_remove = backtrack(start + 1, count)
        # Option 2: Include the current interval if it doesn't overlap with the last included
        if not intervals or intervals[start][0] >= intervals[-1][1]:
            min_remove = min(min_remove, backtrack(start + 1, count + 1))
        return min_remove

    return backtrack(0, 0)
