def solve(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    for start in range(n):
        if not visited[start]:
            queue = deque()
            queue.append((start, -1))  # (current node, parent)
            visited[start] = True
            while queue:
                node, parent = queue.popleft()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
