def solve(n, prerequisites):
    from collections import defaultdict

    graph = defaultdict(list)
    in_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    result = []

    def backtrack(path, in_degree):
        if len(path) == n:
            result.extend(path)
            return True
        for node in range(n):
            if in_degree[node] == 0 and node not in path:
                in_degree[node] = -1
                for neighbor in graph[node]:
                    in_degree[neighbor] -= 1
                path.append(node)
                if backtrack(path, in_degree):
                    return True
                path.pop()
                for neighbor in graph[node]:
                    in_degree[neighbor] += 1
                in_degree[node] = 0
        return False

    if backtrack([], in_degree):
        return result
    else:
        return []
