        left, right = 0, len(nums) - 1
        res = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            elif nums[mid] > target:
                right = mid - 1
            else:
                res = mid
                left = mid + 1
        return res

    first = find_first()
    if first == -1:
        return [-1, -1]
    last = find_last()
    return [first, last]
