    if len(needle) > len(haystack):
        return -1
    n = len(haystack)
    m = len(needle)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if haystack[i - 1] == needle[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = 0
    for i in range(n, 0, -1):
        if dp[i][m] == m:
            return i - m
    return -1
