        return [a[0]*b[0] + a[1]*b[2], a[0]*b[1] + a[1]*b[3], a[2]*b[0] + a[3]*b[2], a[2]*b[1] + a[3]*b[3]]

    def power(matrix, n):
        result = [1, 0, 0, 1]
        while n > 0:
            if n % 2 == 1:
                result = multiply(result, matrix)
            matrix = multiply(matrix, matrix)
            n //= 2
        return result

    if n == 0:
        return 0
    elif n == 1:
        return 1
    matrix = [1, 1, 1, 0]
    powered = power(matrix, n - 1)
    return powered[0]
