def solve(nums):
    def divides_fast(i, j):
        return i % j == 0

    def dfs(i, j):
        if i == len(nums):
            return 0
        if j == len(nums):
            return 1
        if divides_fast(nums[i], nums[j]):
            return 1 + dfs(i + 1, i)
        else:
            return dfs(i + 1, j)

    return dfs(0, 0)
```

