from collections import deque

def solve(intervals):
    if not intervals:
        return []
    intervals.sort()
    merged = deque([intervals[0]])
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])
    return list(merged)
