def solve(intervals):
    if not intervals:
        return []
    # Convert intervals to start and end - 1 to handle inclusive end
    events = []
    for start, end in intervals:
        events.append((start, 1))
        events.append((end, -1))
    # Sort events by position, and by type (end before start to handle [3,5] and [5,7])
    events.sort(key=lambda x: (x[0], x[1]))
    merged = []
    current_start = None
    current_end = None
    for pos, typ in events:
        if typ == 1:
            if current_start is None:
                current_start = pos
            current_end = max(current_end, pos)
        else:
            if current_start is not None:
                merged.append([current_start, current_end])
                current_start = None
                current_end = None
    return merged
```

