from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    sorted_counts = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    result = []
    current_freq = sorted_counts[0][1]
    current_group = [sorted_counts[0][0]]

    for num, freq in sorted_counts[1:]:
        if freq == current_freq:
            current_group.append(num)
        else:
            if len(current_group) < k:
                result.extend(current_group)
            else:
                break
            current_freq = freq
            current_group = [num]

    if len(result) < k:
        result.extend(current_group[:k - len(result)])

    return result
