import heapq

def solve(intervals):
    if not intervals:
        return 0
    # Sort intervals by their end times
    intervals.sort(key=lambda x: x[1])
    # Use a max heap to track the end times of selected intervals
    heap = []
    for start, end in intervals:
        if not heap or start >= heap[0]:
            heapq.heappush(heap, end)
        else:
            # Replace the interval with the current one if it starts after the earliest end
            heapq.heappop(heap)
            heapq.heappush(heap, end)
    return len(intervals) - len(heap)
