def solve(n, prerequisites):
    from collections import defaultdict, deque

    def kosaraju(graph, reversed_graph):
        visited = [False] * n
        order = []

        def dfs(u):
            visited[u] = True
            for v in graph[u]:
                if not visited[v]:
                    dfs(v)
            order.append(u)

        for i in range(n):
            if not visited[i]:
                dfs(i)

        visited = [False] * n
        component = [0] * n
        current_component = 0

        def reverse_dfs(u, current_component):
            visited[u] = True
            component[u] = current_component
            for v in reversed_graph[u]:
                if not visited[v]:
                    reverse_dfs(v, current_component)

        for u in reversed(order):
            if not visited[u]:
                reverse_dfs(u, current_component)
                current_component += 1

        return component

    graph = defaultdict(list)
    reversed_graph = defaultdict(list)
    for a, b in prerequisites:
        graph[a].append(b)
        reversed_graph[b].append(a)

    component = kosaraju(graph, reversed_graph)
    components = defaultdict(list)
    for i in range(n):
        components[component[i]].append(i)

    for c in components.values():
        if len(c) > 1:
            return []

    return list(components[0])
